source("pre.R")
x <- t(id_from_bytes(as.raw(rep(255, 8)), "scru64"))
p("scru64 ff bytes back", id_bytes(x)); p("valid struct", id_valid(as.character(x), "scru64", level="syntax"))
p("scru64 36^12", {b <- as.raw(c(0x41,0xc2,0x1c,0xb8,0xe1,0,0,0)); y <- id_from_bytes(b, "scru64"); print(y); id_bytes(y)})
p("scru64 36^12-1", {b <- as.raw(c(0x41,0xc2,0x1c,0xb8,0xe0,0xff,0xff,0xff)); y <- id_from_bytes(b, "scru64"); print(y); id_bytes(y)})
p("scru128 ff bytes", identical(as.vector(id_bytes(id_from_bytes(as.raw(rep(255,16)), "scru128"))), as.raw(rep(255,16))))
p("hex parse", id_parse(c("018f6b1c2d3e7a4b8c5d6e7f8091a2b3","018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3","018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B3","0-1-8f6b1c2d3e7a4b8c5d6e7f8091a2b3"), "uuid", form="hex"))
p("decode hex hyphens", id_decode("0-1-8f6b1c2d3e7a4b8c5d6e7f8091a2b3", "hex"))
# class behaviour
tw <- id_layout("twitter"); dc <- id_layout("discord")
s1 <- id_parse(c("9","10","1541815603606036480","100"), "snowflake", layout=tw)
p("sort snowflake", as.character(sort(s1))); p("order", order(s1)); p("sort dec", as.character(sort(s1, decreasing=TRUE)))
p("sort NA", as.character(sort(c(s1, NA)))); p("sort na.last", as.character(sort(c(s1, NA), na.last=TRUE)))
p("rank", rank(s1)); p("xtfrm", xtfrm(c(s1, NA)))
s2 <- id_parse("9", "snowflake", layout=dc)
p("c diff layouts", c(s1, s2)); p("== diff layouts", s1[1] == s2); p("[<- diff layout", {y <- s1; y[1] <- s2; y})
p("c char", c(s1, "77")); p("c char bad", c(s1, "0077")); p("c num", c(s1, 77)); p("c NA", c(s1, NA)); p("c NULL", c(s1, NULL)); p("c factor", c(s1, factor("77")))
p("layout kept after [", identical(attr(s1[2:3], "layout"), tw)); p("layout kept unique/rep/rev/sort", c(identical(attr(unique(s1),"layout"),tw), identical(attr(rep(s1,2),"layout"),tw), identical(attr(sort(s1),"layout"),tw)))
p("%in%", s1 %in% "9"); p("match numeric", match(9, s1)); p("== num", s1 == 9); p("== 1e5", id_parse("100000","snowflake",layout=tw) == 1e5); p("== 1e15", id_parse("1000000000000000","snowflake",layout=tw) == 1e15)
p("== big", id_parse("123456789012345678","snowflake",layout=tw) == 123456789012345678)
p("== int", s1 == 9L); p("== recycle", s1 == c("9","10")); p("!=", s1 != "9"); p("<", s1 < "9"); p("== NA", s1 == NA)
u <- id_parse("018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3", "uuid")
p("== upper", u == "018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B3"); p("== urn", u == "urn:uuid:018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3"); p("%in% upper", u %in% "018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B3")
p("char == zuid", "018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B3" == u); p("== factor", u == factor("018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B3"))
p("uuid==ulid", u == id_convert(u, "ulid")); p("identical after conversions", identical(id_convert(id_convert(u,"ulid"),"uuid"), u))
ty <- id_parse(c("user_01h2xcejqtf2nbrexx3vqjhp41","01h2xcejqtf2nbrexx3vqjhp41"), "typeid")
p("typeid ==", ty == "USER_01H2XCEJQTF2NBREXX3VQJHP41"); p("typeid upper valid", id_valid(c("user_01H2XCEJQTF2NBREXX3VQJHP41","01H2XCEJQTF2NBREXX3VQJHP41"), "typeid"))
p("ulid lower", id_parse("01h2xcejqtf2nbrexx3vqjhp41", "ulid")); p("ulid ILO", id_valid(c("01H2XCEJQTF2NBREXX3VQJHPIL","O1H2XCEJQTF2NBREXX3VQJHP41"), "ulid"))
# [<- variants
p("[<- name", {y <- c(a=u); y["zz"] <- "018F6B1C-2D3E-7A4B-8C5D-6E7F8091A2B4"; y}); p("[<- extend", {y <- u; y[3] <- u; y}); p("[[<-", {y <- u; y[[1]] <- NA; y}); p("[<- logical idx", {y <- c(u,u); y[c(TRUE,FALSE)] <- NA; y})
p("[<- bad", {y <- u; y[1] <- "nope"; y}); p("[<- list", {y <- u; y[1] <- list("018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b4"); y}); p("[<- num", {y<-u; y[1] <- 5; y})
p("[<- form compact", {y <- u; y[1] <- "018f6b1c2d3e7a4b8c5d6e7f8091a2b3"; y})
# data frames
df <- data.frame(id = c(u, uuid_nil()), k = 1:2); p("df class", class(df$id)); p("df order", df[order(df$id), ]); p("rbind", class(rbind(df, df)$id)); p("merge", class(merge(df, df, by="id")$id))
p("df $<- factor", {df$id[1] <- factor("018f6b1c-2d3e-7a4b-8c5d-6e7f8091a2b3"); df})
p("as.data.frame", names(as.data.frame(u))); p("format NA", format(c(u, NA))); p("paste", paste(u)); p("toString", toString(c(u,NA)))
p("duplicated", duplicated(c(u,u))); p("table", dim(table(c(u,u)))); p("factor", levels(factor(u))); p("ifelse", class(ifelse(TRUE, u, u))); p("split", class(split(c(u,u), 1:2)[[1]]))
p("summary", summary(u)); p("str", str(u)); p("nchar", nchar(u)); p("is.na", is.na(c(u,NA))); p("anyNA", anyNA(c(u, NA))); p("append", class(append(u, u))); p("setdiff", class(setdiff(c(u, uuid_nil()), u))); p("sapply", sapply(c(u,u), class)); p("vapply names", names(vapply(c(u,u), nchar, 1L))); p("mapply", names(sapply(u, identity)))
